attempts.sop:
@us nlu.entity pronoun="us"
@heading nlu.entity determiner="a" head="heading"
@intro nlu.entity literal="Intro"
@paragraph nlu.entity determiner="a" head="paragraph"
@quote nlu.entity literal="Please confirm these updated details."
@let nlu.clause form=imperative predicate="Let" direct_object=$us clausal_complement=$add
@add nlu.clause form=nonfinite predicate="add" direct_object=$heading
@name nlu.relation kind=name from=$heading to=$intro cue="called"
@make nlu.clause form=imperative predicate="make" direct_object=$paragraph
@content nlu.relation kind=content from=$paragraph to=$quote cue="saying"
@that nlu.entity pronoun="That"
@help nlu.clause form=declarative subject=$that auxiliary="would" predicate="help"
@sequence nlu.coordination kind=sequence member=$let member=$make member=$help cue="then"

@red nlu.entity determiner="the" modifier="red" head="block"
@blue nlu.entity determiner="the" modifier="blue" head="block"
@blocks nlu.coordination kind=and member=$red member=$blue cue="and"
@right_place nlu.entity quantity="one" head="place"
@left_place nlu.entity quantity="one" head="place"
@move nlu.clause form=imperative predicate="move" direct_object=$blocks
@right nlu.relation kind=direction from=$red to=$right_place cue="right"
@left nlu.relation kind=direction from=$blue to=$left_place cue="left"
@swap nlu.entity determiner="the" head="swap"
@pair nlu.entity determiner="the" head="pair"
@undo nlu.clause form=imperative predicate="undo" direct_object=$swap
@affected nlu.relation kind=affected from=$swap to=$pair cue="for"
@gap nlu.entity determiner="the" head="gap"
@them nlu.entity pronoun="them"
@between nlu.relation kind=between from=$gap to=$them cue="between"
@it nlu.entity pronoun="it"
@is nlu.clause form=declarative subject=$it predicate="is"
@as nlu.relation kind=manner from=$gap to=$is cue="as"
@leave nlu.clause form=imperative predicate="leave" direct_object=$gap
@sequence nlu.coordination kind=sequence member=$move member=$undo member=$leave cue="then" cue="then"

@i nlu.entity pronoun="I"
@bench nlu.entity determiner="the" modifier="old" head="bench"
@bit nlu.entity determiner="a" head="bit"
@tree nlu.entity determiner="the" head="tree"
@want nlu.clause form=declarative subject=$i predicate="want" direct_object=$bench
@closer nlu.relation kind=proximity from=$bench to=$tree cue="closer to" measure=$bit
@path nlu.entity determiner="the" head="path"
@leave nlu.clause form=imperative predicate="leave" direct_object=$path result_complement="clear"
@and nlu.coordination kind=and member=$want member=$leave cue="and"

@you nlu.entity pronoun="you"
@chart nlu.entity determiner="a" compound="line" head="chart"
@data nlu.entity modifier="sample" head="data"
@fill nlu.clause form=interrogative auxiliary="can" subject=$you predicate="fill" direct_object=$chart terminator="!"
@with nlu.relation kind=instrument from=$fill to=$data cue="with"

@label nlu.entity determiner="the" head="label"
@fit nlu.clause form=declarative filler="hmm" subject=$label auxiliary="does" negation="not" predicate="fit" separator=","
@one nlu.entity determiner="the" modifier="highlighted" head="one"
@width nlu.entity quantity="160"
@make nlu.clause form=imperative predicate="make" direct_object=$one result_complement="wide"
@measure nlu.relation kind=measure from=$make to=$width

@lift nlu.entity name="Lift"
@make nlu.clause form=imperative filler="Hey" separator="," predicate="make" direct_object=$lift result_color=blue terminator="."
@that nlu.entity pronoun="That"
@help nlu.clause form=declarative subject=$that auxiliary="would" predicate="help" terminator="."

@me nlu.entity pronoun="me"
@chart nlu.entity determiner="a" compound="line" head="chart"
@sales nlu.entity determiner="the" modifier="avg" head="sales"
@month nlu.entity determiner="each" head="month"
@give nlu.clause form=imperative predicate="give" indirect_object=$me direct_object=$chart separator=";"
@of nlu.relation kind=content from=$chart to=$sales cue="of"
@for nlu.relation kind=distribution from=$sales to=$month cue="for"
@legend nlu.entity determiner="the" head="legend"
@right nlu.entity determiner="the" head="right"
@move nlu.clause form=imperative connective="and" predicate="move" direct_object=$legend
@to nlu.relation kind=destination from=$move to=$right cue="to"
